from typing import Any, Literal, Annotated, Union
from pydantic import BaseModel, Discriminator
from fastapi import FastAPI
from fastapi.testclient import TestClient

class Pie(BaseModel):
    time_to_cook: int
    num_ingredients: int

class ApplePie(Pie):
    fruit: Literal["apple"] = "apple"

class PumpkinPie(Pie):
    filling: Literal["pumpkin"] = "pumpkin"

def get_discriminator_value(v):
    if isinstance(v, ApplePie):
        return "apple"
    if isinstance(v, PumpkinPie):
        return "pumpkin"
    return "unknown"

Dessert = Annotated[
    Union[ApplePie, PumpkinPie],
    Discriminator(get_discriminator_value),
]

app = FastAPI()

@app.post("/dessert")
async def dinner(dessert: Dessert) -> dict[str, Any]:
    return dessert.model_dump()

client = TestClient(app)

def test_repro():
    # If it's a body parameter, this should work (or fail with Pydantic error, but not 422 missing query param)
    # If it's a query parameter, this will fail with 422 because 'dessert' is missing from query
    payload = {"fruit": "apple", "time_to_cook": 30, "num_ingredients": 5}
    response = client.post("/dessert", json=payload)
    print(f"Status code: {response.status_code}")
    print(f"Response body: {response.json()}")
    assert response.status_code != 422, "Should not be 422 (missing query param)"

if __name__ == "__main__":
    try:
        test_repro()
        print("Test passed!")
    except Exception as e:
        print(f"Test failed: {e}")

